module tb;
    reg        sel;
    reg  [7:0] a;
    reg  [7:0] b;
    wire [7:0] out;

    TopModule dut (
        .sel(sel),
        .a(a),
        .b(b),
        .out(out)
    );

    initial begin
        // Test case 1: sel = 0, expect a
        sel = 0; a = 8'hA5; b = 8'h5A;
        #10;
        if (out !== 8'hA5) begin
            $display("SELFTEST FAIL: sel=0, a=%h, b=%h, got=%h, expected=%h", a, b, out, a);
            $finish;
        end

        // Test case 2: sel = 1, expect b
        sel = 1; a = 8'hA5; b = 8'h5A;
        #10;
        if (out !== 8'h5A) begin
            $display("SELFTEST FAIL: sel=1, a=%h, b=%h, got=%h, expected=%h", a, b, out, b);
            $finish;
        end

        // Test case 3: edge cases (zeros, ones)
        sel = 0; a = 8'h00; b = 8'hFF;
        #10;
        if (out !== 8'h00) begin
            $display("SELFTEST FAIL: sel=0, a=%h, b=%h, got=%h, expected=%h", a, b, out, a);
            $finish;
        end

        sel = 1; a = 8'h00; b = 8'hFF;
        #10;
        if (out !== 8'hFF) begin
            $display("SELFTEST FAIL: sel=1, a=%h, b=%h, got=%h, expected=%h", a, b, out, b);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
